/bin/bash -lc "python - <<'PY'
import urllib.request, re
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://platform.openai.com/docs/guides/your-data']:
    try:
        page=urllib.request.urlopen(url, timeout=30).read().decode()
        text=re.sub('<["'^>]+>'"', ' ', page)
        text=re.sub(r'\\s+', ' ', text)
        print(url)
        for term in ['store', 'input', '30 days', 'abuse monitoring']:
            match=re.search(r'.{0,120}\\b'+term+r'\\b.{0,350}', text, re.I)
            if match: print(match.group())
    except Exception as exc:
        print(type(exc).__name__)
PY"

